function applyDataTranslations(langSuffix = '_zh') {
    if (typeof caseStudiesData !== 'undefined') {
        for (let k in caseStudiesData) {
            for (let prop in caseStudiesData[k]) {
                if (prop.endsWith(langSuffix)) {
                    caseStudiesData[k][prop.replace(langSuffix, '')] = caseStudiesData[k][prop];
                }
            }
        }
    }
    if (typeof productsData !== 'undefined') {
        for (let k in productsData) {
            for (let prop in productsData[k]) {
                if (prop.endsWith(langSuffix)) {
                    productsData[k][prop.replace(langSuffix, '')] = productsData[k][prop];
                }
            }
        }
    }
    if (typeof leadershipData !== 'undefined') {
        for (let k in leadershipData) {
            for (let prop in leadershipData[k]) {
                if (prop.endsWith(langSuffix)) {
                    leadershipData[k][prop.replace(langSuffix, '')] = leadershipData[k][prop];
                }
            }
        }
    }
}

function translateDOM(node, dict = staticTranslations, lang = 'zh') {
    if (node.nodeType === 3) {
        let rawTxt = node.nodeValue;
        // Normalize whitespace and newlines for lookup
        let txt = rawTxt.trim().replace(/\s+/g, ' ');

        if (txt && dict[txt]) {
            // Extract the core text (without leading/trailing spaces) to replace
            let trimMatch = rawTxt.match(/^\s*([\s\S]*?)\s*$/);
            if (trimMatch && trimMatch[1]) {
                node.nodeValue = rawTxt.replace(trimMatch[1], dict[txt]);
            }
        } else if (txt) {
            // Catch variations of arrow like standard arrow vs unicode char
            if (txt === 'Read Case Study →' || txt === 'Read Case Study') {
                let trimMatch = rawTxt.match(/^\s*([\s\S]*?)\s*$/);
                if (trimMatch && trimMatch[1]) {
                    let translatedText = 'Read Case Study →';
                    if (lang === 'zh') translatedText = '阅读案例研究 →';
                    else if (lang === 'es') translatedText = 'Leer estudio de caso →';
                    else if (lang === 'fr') translatedText = 'Lire l\'Étude de cas →';
                    else if (lang === 'de') translatedText = 'Fallstudie lesen →';
                    node.nodeValue = rawTxt.replace(trimMatch[1], translatedText);
                }
            }
        }
    } else if (node.nodeType === 1) {
        if (node.tagName === 'SCRIPT' || node.tagName === 'STYLE') return;
        for (let i = 0; i < node.childNodes.length; i++) {
            translateDOM(node.childNodes[i], dict, lang);
        }
    }
}


