function initTranslation() {
    let lang = localStorage.getItem('averence_lang');
    if (lang === 'zh') {
        applyDataTranslations('_zh'); // Patch data structs before DOMContentLoaded
        // Set up translation observer/DOM walk
        // Since we are loading script at end of body, we can walk DOM immediately for pre-existing static HTML
        translateDOM(document.documentElement, staticTranslations, 'zh');

        // As scripts like products.js will run on DOMContentLoaded and overwrite some text, 
        // we should also hook into that
        document.addEventListener('DOMContentLoaded', () => {
            // Slight delay to ensure their DOMContentLoaded runs first
            setTimeout(() => { translateDOM(document.documentElement, staticTranslations, 'zh'); }, 50);
        });
    } else if (lang === 'es') {
        applyDataTranslations('_es');
        translateDOM(document.documentElement, staticTranslationsES, 'es');

        document.addEventListener('DOMContentLoaded', () => {
            setTimeout(() => { translateDOM(document.documentElement, staticTranslationsES, 'es'); }, 50);
        });
    } else if (lang === 'fr') {
        applyDataTranslations('_fr');
        translateDOM(document.documentElement, staticTranslationsFR, 'fr');

        document.addEventListener('DOMContentLoaded', () => {
            setTimeout(() => { translateDOM(document.documentElement, staticTranslationsFR, 'fr'); }, 50);
        });
    } else if (lang === 'de') {
        applyDataTranslations('_de');
        translateDOM(document.documentElement, staticTranslationsDE, 'de');

        document.addEventListener('DOMContentLoaded', () => {
            setTimeout(() => { translateDOM(document.documentElement, staticTranslationsDE, 'de'); }, 50);
        });
    }

    // Attach click events to all languages
    document.addEventListener('DOMContentLoaded', () => {
        const links = document.querySelectorAll('.dropdown-menu a');
        links.forEach(link => {
            link.addEventListener('click', (e) => {
                const text = e.target.innerText.trim();

                if (text === 'English') {
                    e.preventDefault();
                    localStorage.removeItem('averence_lang');
                    location.reload();
                } else if (text === '中文') {
                    e.preventDefault();
                    localStorage.setItem('averence_lang', 'zh');
                    location.reload();
                } else if (text === 'Español') {
                    e.preventDefault();
                    localStorage.setItem('averence_lang', 'es');
                    location.reload();
                } else if (text === 'Français') {
                    e.preventDefault();
                    localStorage.setItem('averence_lang', 'fr');
                    location.reload();
                } else if (text === 'Deutsch') {
                    e.preventDefault();
                    localStorage.setItem('averence_lang', 'de');
                    location.reload();
                }
            });
        });

        // Also update the dropdown button text
        if (lang === 'zh' || lang === 'es' || lang === 'fr') {
            document.querySelectorAll('.lang-desktop > a, .lang-mobile > a').forEach(aEl => {
                // The structure is <i class="fas fa-globe"></i> Language <i class="..."></i>
                Array.from(aEl.childNodes).forEach(node => {
                    if (node.nodeType === 3 && node.nodeValue.trim() === 'Language') {
                        let newLabel = lang === 'zh' ? '语言' : (lang === 'es' ? 'Español' : 'Langue');
                        node.nodeValue = node.nodeValue.replace('Language', newLabel);
                    }
                });
            });
        }
    });
}

initTranslation();
